import { createHmac, timingSafeEqual } from 'crypto'

export interface TokenValidationResult {
  valid: boolean
  timestamp?: number
  reason?: string
}

/**
 * Validates the HMAC-SHA256 token generated by Node Z buffer.
 * - Extracts timestamp and signature: ${timestamp}.${signature}
 * - Checks TTL (expiration)
 * - Computes expected HMAC using SECRET_SALT
 * - Compares with timing-safe equality to protect against timing attacks
 */
export function validateZToken(
  token: string,
  secretSalt: string,
  maxAgeSeconds = 300
): TokenValidationResult {
  if (!token || typeof token !== 'string') {
    return { valid: false, reason: 'Missing token' }
  }

  const parts = token.split('.')
  if (parts.length !== 2) {
    return { valid: false, reason: 'Invalid token structure' }
  }

  const [timestampStr, signature] = parts
  const timestamp = parseInt(timestampStr, 10)
  const now = Math.floor(Date.now() / 1000)

  if (isNaN(timestamp)) {
    return { valid: false, reason: 'Invalid timestamp format' }
  }

  // Validate TTL expiration (default 300s = 5 minutes)
  if (now - timestamp > maxAgeSeconds) {
    return { valid: false, reason: 'Token expired' }
  }

  // Future timestamp clock drift protection (> 30s)
  if (timestamp - now > 30) {
    return { valid: false, reason: 'Future timestamp detected' }
  }

  // Recompute expected HMAC signature
  const expectedSignature = createHmac('sha256', secretSalt)
    .update(`session-${timestamp}`)
    .digest('hex')

  const sigBuffer = Buffer.from(signature, 'utf8')
  const expectedBuffer = Buffer.from(expectedSignature, 'utf8')

  if (sigBuffer.length !== expectedBuffer.length || !timingSafeEqual(sigBuffer, expectedBuffer)) {
    return { valid: false, reason: 'Signature mismatch' }
  }

  return { valid: true, timestamp }
}
